"""
Document parser — n8n Python Code block.

In n8n's Code node (Python mode), paste this file and uncomment the
entry-point line at the very bottom:

    return process_items(items)

Input  : one or more n8n items, each carrying a binary property with the
         document bytes (PDF / DOCX / TXT / MD).
Output : same items enriched with a 'parsed' key containing:
           format       – "pdf" | "docx" | "txt"
           file_name    – original file name
           full_text    – all extracted text joined
           pages        – list of {page, text[, image_descriptions]}

Configuration (edit here or inject via n8n Set node upstream):
    BINARY_PROPERTY  name of the binary property on each item (default "data")
    USE_VISION       pass embedded images to Gemini Vision (default False)
    GEMINI_API_KEY   read from environment; override here if needed

Dependencies — must be installed in the Python environment n8n uses:
    pdfplumber           PDF parsing (pure Python)
    python-docx          DOCX parsing
    google-genai         Gemini Vision (only when USE_VISION = True)
"""

import base64
import os
import tempfile
from pathlib import Path

# ── configuration ─────────────────────────────────────────────────────────────

BINARY_PROPERTY = "data"
USE_VISION = True
GEMINI_API_KEY = os.environ.get("GEMINI_API_KEY", "")

# ── Gemini Vision ──────────────────────────────────────────────────────────────

def _describe_images(image_bytes_list, api_key):
    try:
        from google import genai
        from google.genai import types
    except ImportError:
        return ["[google-genai not installed; run: poetry add google-genai]"] * len(image_bytes_list)

    client = genai.Client(api_key=api_key)

    descriptions = []
    for img_bytes in image_bytes_list:
        response = client.models.generate_content(
            model="gemini-2.5-flash-image",
            contents=[
                types.Part.from_bytes(data=img_bytes, mime_type="image/png"),
                "Describe the content of this image concisely.",
            ],
        )
        descriptions.append(response.text.strip())
    return descriptions


def _vision_result(image_bytes_list, api_key):
    if not image_bytes_list:
        return None
    if not api_key:
        return ["[GEMINI_API_KEY not set]"] * len(image_bytes_list)
    return _describe_images(image_bytes_list, api_key)


# ── parsers ───────────────────────────────────────────────────────────────────

def _parse_pdf(path, use_vision, api_key):
    import pdfplumber
    from pdfminer.layout import LTFigure, LTImage

    with pdfplumber.open(path) as pdf:
        pages = []
        text_parts = []

        for i, page in enumerate(pdf.pages):
            text = page.extract_text() or ""
            page_data = {"page": i + 1, "text": text}

            if use_vision:
                img_bytes_list = []
                for item in page.layout:
                    if isinstance(item, LTFigure):
                        for sub in item:
                            if isinstance(sub, LTImage):
                                try:
                                    img_bytes_list.append(sub.stream.get_rawdata())
                                except Exception:
                                    pass
                descriptions = _vision_result(img_bytes_list, api_key)
                if descriptions is not None:
                    page_data["image_descriptions"] = descriptions

            pages.append(page_data)
            text_parts.append(text)

        return {
            "format": "pdf",
            "total_pages": len(pdf.pages),
            "full_text": "\n\n".join(text_parts),
            "pages": pages,
        }


def _parse_docx(path, use_vision, api_key):
    try:
        from docx import Document
    except ImportError:
        return {"error": "python-docx not installed; run: poetry add python-docx"}

    doc = Document(path)
    full_text = "\n".join(p.text for p in doc.paragraphs)

    result = {
        "format": "docx",
        "full_text": full_text,
        "pages": [{"page": 1, "text": full_text}],
    }

    if use_vision:
        img_bytes_list = []
        for rel in doc.part.rels.values():
            if "image" in rel.reltype:
                try:
                    img_bytes_list.append(rel.target_part.blob)
                except Exception:
                    pass
        descriptions = _vision_result(img_bytes_list, api_key)
        if descriptions is not None:
            result["pages"][0]["image_descriptions"] = descriptions

    return result


def _parse_text(path):
    text = Path(path).read_text(encoding="utf-8", errors="replace")
    return {
        "format": "txt",
        "full_text": text,
        "pages": [{"page": 1, "text": text}],
    }


# ── helpers ───────────────────────────────────────────────────────────────────

def _to_bytes(data):
    """Accept raw bytes, standard base64, or URL-safe base64 from n8n."""
    if isinstance(data, (bytes, bytearray)):
        return bytes(data)
    s = data.strip()
    try:
        return base64.b64decode(s)
    except Exception:
        return base64.urlsafe_b64decode(s + "==")


# ── n8n item processor ────────────────────────────────────────────────────────

def process_items(items, binary_property=BINARY_PROPERTY, use_vision=USE_VISION, api_key=GEMINI_API_KEY):
    output = []

    for item in items:
        json_data = item.get("json", {})

        # API key: prefer value injected via Set node ($env.GEMINI_API_KEY expression)
        # over the module-level os.environ read (which n8n's sandbox may block)
        effective_api_key = json_data.get("_geminiApiKey", "") or api_key

        # filesystem-v2 mode: a JS Code node upstream extracted bytes into JSON
        raw = json_data.get("_fileBase64", "")
        file_name = json_data.get("_fileName", "document")

        # default (in-memory) mode: bytes are base64 in the binary property
        if not raw:
            binary = item.get("binary", {}).get(binary_property, {})
            raw = binary.get("data", "")
            file_name = binary.get("fileName", file_name)

        if not raw:
            output.append({"json": {**json_data, "error": "no binary data found"}})
            continue

        file_bytes = _to_bytes(raw)
        ext = Path(file_name).suffix.lower()

        tmp_path = None
        try:
            with tempfile.NamedTemporaryFile(suffix=ext, delete=False) as tmp:
                tmp.write(file_bytes)
                tmp_path = tmp.name

            if ext == ".pdf":
                parsed = _parse_pdf(tmp_path, use_vision, effective_api_key)
            elif ext == ".docx":
                parsed = _parse_docx(tmp_path, use_vision, effective_api_key)
            elif ext in (".txt", ".md"):
                parsed = _parse_text(tmp_path)
            else:
                parsed = {"error": f"unsupported file type: {ext}"}

            parsed["file_name"] = file_name

        except Exception as e:
            parsed = {"error": str(e), "file_name": file_name}
        finally:
            if tmp_path:
                os.unlink(tmp_path)

        output.append({"json": {**item.get("json", {}), "parsed": parsed}})

    return output


# ── n8n Code node entry point ─────────────────────────────────────────────────
# Uncomment the line below when pasting into n8n's Python Code node:
return process_items(_items)

parameters.jsCode:
const text = $input.first().json.parsed?.full_text ?? $input.first().json.full_text ?? "";
const excerpt = text.slice(0, 1000);

const prompt = `## Task
Read the document excerpt below and classify it into exactly one of these domain scenarios:

- **business**      — general corporate communications, operations, memos
- **cybersecurity** — incident reports, threat intelligence, security audits
- **financial**     — financial statements, investment reports, budgets
- **hr**            — employment contracts, performance reviews, HR policies
- **product**       — product descriptions, specs, market positioning
- **academic**      — research papers, studies, academic articles
- **legal**         — contracts, regulations, legal proceedings, compliance
- **medical**       — clinical notes, diagnoses, treatment plans, lab results
- **other**         — does not clearly fit any of the above domains

## Example

<example>
  <input>This agreement is entered into by and between Acme Corp and John Smith effective January 1, 2024...</input>
  <output>legal</output>
</example>

## Document Excerpt
${excerpt}`;

const requestBody = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0,
    responseMimeType: "application/json",
    responseSchema: {
      type: "object",
      properties: {
        scenario: {
          type: "string",
          enum: ["business", "cybersecurity", "financial", "hr", "product", "academic", "legal", "medical", "other"],
        },
        reasoning: { type: "string" },
      },
      required: ["scenario", "reasoning"],
    },
  },
};

return [{ json: { ...($input.first().json), requestBody } }];

const raw = $input.first().json;
const text = raw.candidates?.[0]?.content?.parts?.[0]?.text ?? "{}";
const { scenario, reasoning } = JSON.parse(text);

// HTTP Request replaced the data — restore original document fields from before the HTTP call
const original = $('Detect Scenario').first().json;

return [{ json: { ...original, detected_scenario: scenario, scenario_reasoning: reasoning } }];

const text = $input.first().json.parsed?.full_text ?? $input.first().json.full_text ?? "";

// Prefer AI-detected scenario, fall back to env var, then default
const scenario = $input.first().json.detected_scenario
  ?? $env.DOCUMENT_SCENARIO
  ?? "business";

const personas = {
  business: {
    role: "You are an expert business document intelligence assistant with deep knowledge of corporate communications, contracts, and operational documents.",
    focus: "Focus on business impact, stakeholder actions, financial figures, and organizational entities.",
  },
  cybersecurity: {
    role: "You are an expert cybersecurity analyst specializing in incident reports, threat intelligence, and security audit documents.",
    focus: "Focus on threat actors, CVEs, affected systems, severity levels, and remediation steps.",
  },
  financial: {
    role: "You are an expert financial analyst with deep knowledge of financial statements, investment reports, and market documents.",
    focus: "Focus on monetary amounts, financial ratios, time periods, risk indicators, and recommended actions.",
  },
  hr: {
    role: "You are an expert HR document specialist with deep knowledge of employment contracts, performance reviews, and HR policies.",
    focus: "Focus on employee names, roles, dates, policy changes, and action items for HR teams.",
  },
  product: {
    role: "You are an expert product analyst specializing in product descriptions, specifications, and market positioning documents.",
    focus: "Focus on product features, target audience, competitive differentiators, and pricing information.",
  },
  academic: {
    role: "You are an expert academic research analyst with broad knowledge across scientific disciplines.",
    focus: "Focus on research objectives, methodologies, key findings, citations, and future research directions.",
  },
  legal: {
    role: "You are an expert legal document analyst with deep knowledge of contracts, regulations, and legal proceedings.",
    focus: "Be precise with party names, dates, obligations, clauses, and deadlines. Flag any ambiguous or high-risk language.",
  },
  medical: {
    role: "You are an expert medical document analyst with deep knowledge of clinical documentation, diagnoses, and treatment plans.",
    focus: "Focus on patient-relevant clinical entities, diagnoses, medications, dosages, and follow-up action items.",
  },
  other: {
    role: "You are a general-purpose document intelligence assistant capable of analyzing any type of document.",
    focus: "Focus on the main subject, key entities, dates, monetary amounts, and any clear action items or decisions.",
  },
};

const persona = personas[scenario] ?? personas.business;

const prompt = `## Role
${persona.role}

## Task
Analyze the document text provided below and extract structured intelligence from it.
${persona.focus}

## Example

<example>
  <input>
    Acme Corp signed a service agreement with TechVendor Ltd on March 12, 2024 for $48,000 annually.
    John Smith (CTO) must approve the renewal by April 1, 2024. The terms include a 30-day termination clause.
  </input>
  <output>
    {
      "summary": "Acme Corp entered a $48,000 annual service agreement with TechVendor Ltd on March 12, 2024. The CTO must approve renewal before April 1, 2024. A 30-day termination clause is included.",
      "classification": "contract",
      "sentiment": "neutral",
      "entities": {
        "people":        ["John Smith"],
        "organizations": ["Acme Corp", "TechVendor Ltd"],
        "dates":         ["March 12, 2024", "April 1, 2024"],
        "amounts":       ["$48,000 annually"]
      },
      "action_items": ["John Smith (CTO) must approve renewal by April 1, 2024"],
      "confidence_score": 0.97
    }
  </output>
</example>

## Rules
- If a field has no relevant data, return an empty array \`[]\` or empty string \`""\`.
- Do not invent information. Only extract what is explicitly stated in the document.
- \`confidence_score\` must reflect actual certainty — use the full 0.0–1.0 range.

## Document
${text}`;

const requestBody = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: "application/json",
    responseSchema: {
      type: "object",
      properties: {
        summary: {
          type: "string",
          description: "2-3 sentence factual summary of the document",
        },
        classification: {
          type: "string",
          enum: ["invoice", "report", "contract", "ticket", "article", "other"],
        },
        sentiment: {
          type: "string",
          enum: ["positive", "neutral", "negative"],
        },
        entities: {
          type: "object",
          properties: {
            people:        { type: "array", items: { type: "string" } },
            organizations: { type: "array", items: { type: "string" } },
            dates:         { type: "array", items: { type: "string" } },
            amounts:       { type: "array", items: { type: "string" } },
          },
        },
        action_items: {
          type: "array",
          items: { type: "string" },
        },
        confidence_score: {
          type: "number",
        },
      },
      required: ["summary", "classification", "sentiment", "entities", "action_items", "confidence_score"],
    },
  },
};

return [{ json: { ...($input.first().json), requestBody } }];

const raw = $input.first().json;
let analysisText = raw.candidates?.[0]?.content?.parts?.[0]?.text ?? "{}";

// Strip markdown code fences if Gemini wraps in ```json
analysisText = analysisText.replace(/^```json\n?/, "").replace(/\n?```$/, "").trim();

let analysis;
try {
  analysis = JSON.parse(analysisText);
} catch (e) {
  throw new Error(`Gemini returned invalid JSON: ${analysisText.substring(0, 200)}`);
}

const required = ["summary", "classification", "sentiment", "entities", "action_items", "confidence_score"];
for (const field of required) {
  if (!(field in analysis)) {
    throw new Error(`Missing required field: ${field}`);
  }
}

return [{ json: { gemini_pro: analysis } }];

const raw = $input.first().json;
let analysisText = raw.candidates?.[0]?.content?.parts?.[0]?.text ?? "{}";

// Strip markdown code fences if Gemini wraps in ```json
analysisText = analysisText.replace(/^```json\n?/, "").replace(/\n?```$/, "").trim();

let analysis;
try {
  analysis = JSON.parse(analysisText);
} catch (e) {
  throw new Error(`Gemini returned invalid JSON: ${analysisText.substring(0, 200)}`);
}

const required = ["summary", "classification", "sentiment", "entities", "action_items", "confidence_score"];
for (const field of required) {
  if (!(field in analysis)) {
    throw new Error(`Missing required field: ${field}`);
  }
}

return [{ json: { gemini_flash: analysis } }];

const general_data = $('Final Result With Models Diff').first().json;
const enrich       = $input.first().json;
const sens         = $input.last().json;

const flash = general_data.gemini_flash;
const pro   = general_data.gemini_pro;

const shared = {
  document_id:       enrich.document_id,
  drive_file_id:     general_data.drive_file_id,
  filename:          general_data.filename,
  file_type:         general_data.file_extension,
  processed_at:      enrich.processed_at,
  department:        enrich.department,
  sensitivity:       sens.sensitivity,
  routing_tag:       enrich.routing_tag,
  flash_vs_pro_diff: JSON.stringify(general_data.flash_vs_pro_diff),
};

return [
  {
    json: {
      ...shared,
      model:            $('Set Gemini Api Key').first().json.gemini_flash_model,
      classification:   flash.classification,
      sentiment:        flash.sentiment,
      confidence_score: flash.confidence_score,
      summary:          flash.summary.slice(0, 500),
      action_items:     flash.action_items.join(', '),
    }
  },
  {
    json: {
      ...shared,
      model:            $('Set Gemini Api Key').first().json.gemini_pro_model,
      classification:   pro.classification,
      sentiment:        pro.sentiment,
      confidence_score: pro.confidence_score,
      summary:          pro.summary.slice(0, 500),
      action_items:     (pro.action_items ?? []).join(', '),
    }
  }
];

const allItems = $input.all();

const flash = allItems.find(i => i.json.gemini_flash)?.json.gemini_flash ?? {};
const pro   = allItems.find(i => i.json.gemini_pro)?.json.gemini_pro   ?? {};

const diff = {
  classification_match: flash.classification === pro.classification,
  sentiment_match:      flash.sentiment === pro.sentiment,
  flash_confidence:     flash.confidence_score,
  pro_confidence:       pro.confidence_score ?? null,
  flash_summary:        flash.summary,
  pro_summary:          pro.summary ?? null,
};

const scenario = $('Extract Scenario').first().json;

return [{
  json: {
    drive_file_id:      scenario.id,
    filename:           scenario.name,
    file_extension:     scenario.fileExtension,
    mime_type:          scenario.mimeType,
    detected_scenario:  scenario.detected_scenario,
    scenario_reasoning: scenario.scenario_reasoning,
    gemini_flash:       flash,
    gemini_pro:         pro,
    flash_vs_pro_diff:  diff,
    source_zip:         scenario.source_zip ?? "",
  }
}];

// Run once for all items — first = Flash record, last = Pro record
const flash = $input.first().json;
const pro   = $input.last().json;

const diff = JSON.parse(flash.flash_vs_pro_diff);

const jsonReport = JSON.stringify({ flash, pro }, null, 2);

const mdReport = `# Document Analysis Report

**File:** ${flash.filename}
**Processed:** ${flash.processed_at}
**Document ID:** ${flash.document_id}
**Drive File:** ${flash.drive_file_id}

## Classification
- **Type:** ${flash.classification}
- **Department:** ${flash.department}
- **Sensitivity:** ${flash.sensitivity}
- **Routing Tag:** ${flash.routing_tag}
- **File Type:** ${flash.file_type}

## Flash Analysis (${flash.model})
- **Sentiment:** ${flash.sentiment}
- **Confidence:** ${flash.confidence_score}
- **Summary:** ${flash.summary}

## Pro Analysis (${pro.model})
- **Sentiment:** ${pro.sentiment}
- **Confidence:** ${pro.confidence_score}
- **Summary:** ${pro.summary}

## Multi-model Comparison
- Classification match: ${diff.classification_match ? '✅ Match' : '⚠️ Differs'}
- Sentiment match: ${diff.sentiment_match ? '✅ Match' : '⚠️ Differs'}
- Flash confidence: ${diff.flash_confidence}
- Pro confidence: ${diff.pro_confidence ?? 'N/A'}

---
*Generated by Prismatic*
`;

return [{
  json: {
    ...flash,
    json_report: jsonReport,
    md_report:   mdReport,
    base_filename: flash.filename.replace(/\.[^/.]+$/, '')
  }
}];
